urlset:
{{ range .Data.Pages }}
{{- /*
    Exclude pages that should not be crawled, and exclude non-canonical
    pages (those whose  points elsewhere — e.g.
    versioned package docs at /registry/packages/@/ whose
    canonical points to the unversioned sibling). See #10639.

    This is the only sitemap template in the repo (no root-level
    layouts/_default/sitemap.xml exists to keep in sync with).
*/ -}}
{{ $canonicalPath := partial "canonical-path.html" . }}
{{ if and
      (strings.HasPrefix .RelPermalink "/registry")
      (not (or .Params.private .Params.block_external_search_index))
      (not (strings.HasPrefix .RelPermalink "/registry/packages/azure-native-v2"))
      (eq $canonicalPath .RelPermalink) }}
{{- /*
    api-docs pages are generated by resourcedocsgen into a git-ignored
    content directory (see AGENTS.md), so they have no git history and
    .Lastmod is always zero for them. We deliberately do NOT fall back
    to the package's updated_on epoch for these ~58k leaf pages: a
    provider release typically touches a handful of resources, but
    updated_on is a single package-wide timestamp, so falling back to
    it would re-stamp every api-docs page as "modified" on every
    release regardless of whether that specific page changed. That
    mass-restamping wastes crawl budget on unchanged pages and, per
    Google's own guidance, an unreliable lastmod at scale can cause
    the signal to be ignored site-wide — which would also poison the
    genuinely accurate dates on non-api-docs pages below. Omitting
     entirely for api-docs pages (leaving $lastmod zero) is
    more honest than a fabricated date.

    For everything else under a package (the overview page, the
    installation-configuration page, how-to-guides — all committed,
    git-tracked content), .Lastmod already reflects real git history.
    We still prefer the package's own updated_on epoch when it is
    newer, since a new provider release can make the overview page's
    *rendered* content (which pulls from the data file) more current
    than its last git commit even without a new commit to the file
    itself — e.g. oci, azure-native, aws-native have shown stale git
    dates here relative to their real last publish.
*/ -}}
{{ $lastmod := .Lastmod }}
{{ $trimmed := strings.TrimPrefix "/" (strings.TrimSuffix "/" .RelPermalink) }}
{{ $segments := split $trimmed "/" }}
{{ $isApiDocsPage := and (ge (len $segments) 4) (eq (index $segments 3) "api-docs") }}
{{ if and (ge (len $segments) 3) (eq (index $segments 1) "packages") (not $isApiDocsPage) }}
  {{ $packageName := index $segments 2 }}
  {{ with index .Site.Data.registry.packages $packageName }}
    {{ with .updated_on }}
      {{ $pkgLastmod := time . }}
      {{ if or $lastmod.IsZero (gt $pkgLastmod.Unix $lastmod.Unix) }}
        {{ $lastmod = $pkgLastmod }}
      {{ end }}
    {{ end }}
  {{ end }}
{{ end }}

  {{ .Site.Params.canonicalURL }}{{ .RelPermalink }}{{ if not $lastmod.IsZero }}
  {{ safeHTML ( $lastmod.Format "2006-01-02T15:04:05-07:00" ) }}{{ end }}{{ with .Sitemap.ChangeFreq }}
  {{ . }}{{ end }}{{ if ge .Sitemap.Priority 0.0 }}
  {{ .Sitemap.Priority }}{{ end }}{{ if .IsTranslated }}{{ range .Translations }}
  {{ end }}
  {{ end }}

{{ end }}
{{ end }}
